create table if not exists public.enterprise_partner_campaigns (id uuid primary key default gen_random_uuid(), network_id uuid not null references public.enterprise_partner_networks(id) on delete cascade, name text not null, campaign_type text not null default 'engagement', goal text, status text not null default 'draft' check(status in ('draft','active','paused','completed')), created_at timestamptz not null default now(), activated_at timestamptz, paused_at timestamptz, completed_at timestamptz);
create index if not exists epc_network_status_idx on public.enterprise_partner_campaigns(network_id,status);
alter table public.enterprise_partner_campaigns enable row level security;
create or replace function public.create_enterprise_partner_campaign(p_network_id uuid,p_name text,p_campaign_type text default 'engagement',p_goal text default null) returns public.enterprise_partner_campaigns language plpgsql security definer set search_path=public as $$ declare c public.enterprise_partner_campaigns; begin if not exists(select 1 from public.enterprise_partner_networks n where n.id=p_network_id and n.owner_business_id in(select business_id from public.business_members where user_id=auth.uid())) then raise exception 'network access denied'; end if; insert into enterprise_partner_campaigns(network_id,name,campaign_type,goal) values(p_network_id,p_name,p_campaign_type,p_goal) returning * into c; return c; end $$;
create or replace function public.activate_enterprise_partner_campaign(p_campaign_id uuid) returns public.enterprise_partner_campaigns language plpgsql security definer set search_path=public as $$ declare c public.enterprise_partner_campaigns; begin update enterprise_partner_campaigns c0 set status='active',activated_at=coalesce(activated_at,now()),paused_at=null where c0.id=p_campaign_id and c0.network_id in(select id from enterprise_partner_networks where owner_business_id in(select business_id from business_members where user_id=auth.uid())) returning c0.* into c; if not found then raise exception 'campaign access denied'; end if; return c; end $$;
create or replace function public.pause_enterprise_partner_campaign(p_campaign_id uuid) returns public.enterprise_partner_campaigns language plpgsql security definer set search_path=public as $$ declare c public.enterprise_partner_campaigns; begin update enterprise_partner_campaigns c0 set status='paused',paused_at=now() where c0.id=p_campaign_id and c0.network_id in(select id from enterprise_partner_networks where owner_business_id in(select business_id from business_members where user_id=auth.uid())) returning c0.* into c; if not found then raise exception 'campaign access denied'; end if; return c; end $$;
revoke all on function public.create_enterprise_partner_campaign(uuid,text,text,text) from public,anon; revoke all on function public.activate_enterprise_partner_campaign(uuid) from public,anon; revoke all on function public.pause_enterprise_partner_campaign(uuid) from public,anon;
grant execute on function public.create_enterprise_partner_campaign(uuid,text,text,text) to authenticated; grant execute on function public.activate_enterprise_partner_campaign(uuid) to authenticated; grant execute on function public.pause_enterprise_partner_campaign(uuid) to authenticated;
